const $=id=>document.getElementById(id);let song=null,midi=null,busyFlag=false,configured=false;
const token='__TOKEN__';
async function read(path){const r=await fetch(path);const d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function api(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Studio-Token':token},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
function controls(){document.querySelectorAll('button').forEach(b=>b.disabled=busyFlag);if(busyFlag)return;$('copy').disabled=!song;$('import').disabled=!song||song.attempted;$('generate').disabled=!song||song.attempted||!configured||!$('consent').checked;$('prepare').disabled=!song?.adopted||song.attempted;$('apply').disabled=!song?.prepared||song.attempted;$('prepareMidi').disabled=!midi;$('applyMidi').disabled=!midi?.prepared;}
async function work(fn){if(busyFlag)return;busyFlag=true;controls();$('message').textContent='処理中です…';try{await fn()}catch(e){$('message').textContent=e.message}finally{busyFlag=false;controls()}}
async function status(){try{const d=await read('/api/status');$('connection').textContent=d.connected?`Live接続済み · ${d.live.tempo} BPM · ${d.live.tracks.length}トラック`:'Live未接続：Control SurfaceでAbletonGPTを選択';}catch(e){$('connection').textContent='Studioに接続できません'}}
async function providers(){const d=await read('/api/providers');configured=d.api_configured;$('keyState').textContent=configured?'APIキー設定済み（利用権限は生成時に確認）':'APIキー未設定';controls()}
async function history(){const d=await read('/api/projects');$('history').replaceChildren(new Option('曲を選択',''));for(const p of d.projects)$('history').add(new Option(p.title,p.id));}
function render(){if(!song)return;$('compiled').textContent=song.prompt;$('projectLabel').textContent='保存済み · '+song.id.slice(0,8);$('takes').replaceChildren();for(const t of song.takes){const box=document.createElement('div');box.className='take';const info=document.createElement('div');info.textContent=`${t.source==='gemini_api'?'Gemini API / '+t.model:'Flow Music / ユーザー取込'} · ${t.duration_sec.toFixed(1)}秒 · ${t.sample_rate} Hz · ${t.channels}ch`;
const audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.src=`/audio/${song.id}/${t.id}`;const link=document.createElement('a');link.href=audio.src;link.download=t.file;link.textContent='音源を保存';const btn=document.createElement('button');btn.textContent=song.adopted?.take_id===t.id?'採用中':'この音源を採用';btn.onclick=()=>work(async()=>{await api('/api/google/adopt',{id:song.id,take_id:t.id});song.adopted={take_id:t.id};song.prepared=false;$('plan').textContent='';render();$('message').textContent='音源を採用しました。Liveへの追加内容を確認できます。'});if(song.attempted)btn.hidden=true;box.append(info,audio,link,btn);$('takes').append(box)}if(!song.takes.length)$('takes').textContent='まだ音源がありません。Webから取り込むか、APIで生成してください。';controls()}
$('mode').onchange=()=>{$('google').hidden=$('mode').value!=='google';$('midi').hidden=$('mode').value!=='midi'};
$('provider').onchange=()=>{$('flowPane').hidden=$('provider').value!=='flow';$('apiPane').hidden=$('provider').value!=='api'};
$('vocals').onchange=()=>{$('lyricsBox').hidden=$('vocals').value!=='vocal'};
$('consent').onchange=controls;$('refresh').onclick=status;
$('example').onclick=()=>{$('prompt').value='DubとTech House。110 BPM、D#m。太いベースと余白のあるドラム。';$('structure').value='0:00–0:15 イントロ / 0:15–0:50 展開 / 0:50–1:10 ブレイク / 1:10–2:00 クライマックス';};
$('create').onclick=()=>work(async()=>{song=await api('/api/google/project',{prompt:$('prompt').value,duration:Number($('duration').value),vocals:$('vocals').value,lyrics:$('lyrics').value,structure:$('structure').value});$('plan').textContent='';$('consent').checked=false;render();await history();$('message').textContent='生成指示文を保存しました。Web版またはAPI版を選んでください。'});
$('restore').onclick=()=>work(async()=>{if(!$('history').value)throw Error('曲を選択してください');song=await read('/api/project/'+$('history').value);for(const k of ['prompt','duration','vocals','lyrics','structure'])$(k).value=song.brief[k]??'';$('vocals').onchange();$('plan').textContent='';$('consent').checked=false;render();$('message').textContent=song.attempted?'Live追加実行の記録がある曲です。二重追加を禁止しています。':'保存した曲を開きました。'});
$('copy').onclick=()=>work(async()=>{await navigator.clipboard.writeText(song.prompt);$('message').textContent='指示文をコピーしました。Flow Musicへ貼り付けて生成してください。'});
$('setKey').onclick=()=>work(async()=>{const key=$('apiKey').value.trim();if(!key)throw Error('APIキーを入力してください');await api('/api/key',{key});$('apiKey').value='';await providers();$('message').textContent='APIキーを一時設定しました。'});
$('clearKey').onclick=()=>work(async()=>{await api('/api/key',{key:''});$('apiKey').value='';await providers();$('message').textContent='APIキーを解除しました。'});
$('generate').onclick=()=>work(async()=>{if(!$('consent').checked)throw Error('送信内容とAPI利用を確認してください');$('message').textContent='Googleで音源を生成中です。数分かかる場合があります。';const d=await api('/api/google/generate',{id:song.id,model:$('model').value,consent:true});song.takes.push(d.take);$('consent').checked=false;render();$('message').textContent='音源を生成・検証しました。試聴して採用してください。';});
$('import').onclick=()=>work(async()=>{const file=$('upload').files[0];if(!file)throw Error('Flow Musicから保存した音源を選択してください');if(file.size>100*1024*1024)throw Error('100MB以下の音源を選択してください');const suffix='.'+file.name.split('.').pop().toLowerCase();const r=await fetch(`/api/google/upload?id=${song.id}&suffix=${encodeURIComponent(suffix)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Studio-Token':token},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);song.takes.push(d.take);render();$('message').textContent='音源をコピー・検証しました。試聴して採用してください。';});
$('prepare').onclick=()=>work(async()=>{song.prepared=false;const d=await api('/api/prepare',{id:song.id});song.prepared=true;$('plan').textContent=`新規Audioトラック1本に採用音源を追加。Arrangementの先頭に配置。Liveのテンポ ${d.current_tempo} BPMは変更しません。`;$('message').textContent='Liveを停止し、内容を確認して追加してください。'});
$('apply').onclick=()=>work(async()=>{song.prepared=false;song.attempted=true;const d=await api('/api/apply',{id:song.id});$('log').textContent=d.log+'\n'+JSON.stringify(d.status,null,2);$('message').textContent='追加処理が終了しました。Liveで再生し、音源と実行記録を確認してください。';render();await status()});
$('composeMidi').onclick=()=>work(async()=>{midi=null;$('downloads').replaceChildren();const d=await api('/api/compose',{prompt:$('midiPrompt').value,seed:Number($('seed').value)});midi=d;const s=d.spec.song;$('midiResult').textContent=`${s.bpm} BPM / ${s.key} / ${s.total_bars}小節`;$('log').textContent=JSON.stringify(d.spec,null,2);for(const f of d.files.filter(f=>f.endsWith('.mid'))){const a=document.createElement('a');a.href=`/files/${d.id}/${f}`;a.download=f;a.textContent=f;$('downloads').append(a)}$('message').textContent='MIDIを保存しました。'});
$('prepareMidi').onclick=()=>work(async()=>{midi.prepared=false;const d=await api('/api/prepare',{id:midi.id});$('midiPlan').textContent=`テンポ ${d.current_tempo} → ${d.plan.song.bpm} BPM。追加：${d.plan.tracks.map(t=>t.name).join('、')}`;midi.prepared=true;$('message').textContent='追加内容を確認してください。'});
$('applyMidi').onclick=()=>work(async()=>{midi.prepared=false;const d=await api('/api/apply',{id:midi.id});$('log').textContent=d.log;$('message').textContent='追加処理が終了しました。Liveで確認してください。';await status()});
Promise.all([status(),providers(),history()]).catch(e=>{$('message').textContent=e.message});controls();
